                    key: attempt.get(key)
                    for key in (
                        "attempt",
                        "actual_model",
                        "actual_provider",
                        "implementor",
                        "outcome",
                    )
                }
                for attempt in task.get("attempts", [])
            ],
        }
        for task in state.get("tasks", [])
    ]
    return data


